class Solution {
  public int minimumDistance(int[] nums) {
    Map<Integer, List<Integer>> positions = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
      positions.computeIfAbsent(nums[i], v -> new ArrayList<>()).add(i);
    }
    int best = Integer.MAX_VALUE;
    for (List<Integer> p : positions.values()) {
      // for sorted i < j < k the distance is 2 * (k - i); consecutive triples are optimal
      for (int t = 0; t + 2 < p.size(); t++) best = Math.min(best, 2 * (p.get(t + 2) - p.get(t)));
    }
    return best == Integer.MAX_VALUE ? -1 : best;
  }
}
